def __update(self):
    frame = self.__context.getFrame()
    if self.__frame == frame:
        return
    if frame not in self.__validFrames:
        raise ValueError('Invalid frame')
    self.clear()
    for plug in self.__variables.children():
        if 'enabled' in plug and (not plug['enabled'].getValue()):
            continue
        name = plug['name'].getValue()
        if not name:
            continue
        if isinstance(plug['value'], (Gaffer.ObjectPlug, Gaffer.ObjectVectorPlug, Gaffer.CompoundObjectPlug)):
            value = plug['value'].getValue()
        else:
            value = Gaffer.PlugAlgo.getValueAsData(plug['value'])
            with IECore.IgnoredExceptions(Exception):
                value = value.value
        if isinstance(value, str):
            value = self.__context.substitute(value)
        self[name] = value
    self.__frame = frame

def _wait_for_task_token(self, env: Environment, timeout: int = 30) -> None:
    callback_id = env.context_object_manager.context_object["Task"]["Token"]
    callback_endpoint = env.callback_pool_manager.get(callback_id)
    try:
        outcome = callback_endpoint.wait(timeout=timeout)
    except TimeoutError:
        raise TimeoutError(f"Callback for task token '{callback_id}' timed out after {timeout} seconds.")
    if isinstance(outcome, CallbackOutcomeSuccess):
        outcome_output = json.loads(outcome.output)
        env.stack.append(outcome_output)
    elif isinstance(outcome, CallbackOutcomeFailure):
        raise CallbackOutcomeFailureError(callback_outcome_failure=outcome)
    else:
        raise NotImplementedError(f"Unsupported CallbackOutcome type '{type(outcome)}'.").

def load_settings(path=None):
    if not path:
        path = find_settings()

    def update_settings(arg):
        if isinstance(arg, dict):
            config = arg
        else:
            config = parse_settings(arg)
        for key in config:
            setting = config[key]
            if isinstance(setting, dict) and key in settings:
                settings[key].update(setting)
            else:
                settings[key] = setting
    update_settings(os.path.join(PROJDIR, 'tools', '_settings.py'))
