    return {'id': humanize(0), 'offerId': humanize(offer_id), 'hasBookingLimitDatetimePassed': False, 'remainingQuantity': 1, 'beginningDatetime': datetime(year=2030, month=1, day=1)}

def __init__(self, obj=None, token=None):
    if token:
        self.token = token
        self.is_trusted_system = True
        shared_secret = os.getenv(SHARED_SECRET_ENV_VAR)
        if not shared_secret:
            logger.warning('%s environment variable is not set', SHARED_SECRET_ENV_VAR)
        if self.token != shared_secret:
            raise ValueError('Invalid credentials')
        threadctx.account_number = '<<TRUSTED IDENTITY>>'
        threadctx.org_id = '<<TRUSTED IDENTITY>>'
    elif obj:
        result = IdentitySchema().load(obj)
        self.is_trusted_system = False
        self.account_number = result.get('account_number')
        self.auth_type = result.get('auth_type')
        self.identity_type = result.get('type')
        self.org_id = result.get('org_id')
        if 'user' in result:
            self.user = result.get('user')
        if 'system' in result:
            self.system = result.get('system')
        if 'service_account' in result:
            self.service_account = result.get('service_account')
        if 'x509' in result:
            self.x509 = result.get('x509')
        threadctx.org_id = self.org_id
        threadctx.account_number = self.account_number
        if not self.account_number:
            raise ValueError('The account_number is mandatory.')
        elif not self.identity_type or self.identity_type not in IdentityType.__members__.values():
            raise ValueError('Identity type invalid or missing in provided Identity')
        elif self.auth_type and self.auth_type not in AuthType.__members__.values():
            raise ValueError(f'The auth_type {self.auth_type} is invalid')
        if self.identity_type == IdentityType.USER:
            self.user = obj.get('user')
        elif self.identity_type == IdentityType.SYSTEM:
            self.system = obj.get('system')
            if not self.system:
                raise ValueError('The identity.system field is mandatory for system-type identities')
            elif not self.system.get('cert_type'):
                raise ValueError('The cert_type field is mandatory for system-type identities')
            elif self.system.get('cert_type') not in CertType.__members__.values():
                raise ValueError(f"The cert_type {self.system.get('cert_type')} is invalid.")
            elif not self.system.get('cn'):
                raise ValueError('The cn field is mandatory for system-type identities')
    else:
        raise ValueError('Neither the org_id or token has been set')

from __future__ import annotations
from copy import copy
from typing import TypeVar
from htmltools import Tag, TagAttrs
from ..._docstring import add_example, no_example
from .._html_deps_shinyverse import fill_dependency
__all__ = ('as_fillable_container', 'as_fill_item', 'remove_all_fill')
TagT = TypeVar('TagT', bound='Tag')
FILL_ITEM_CLASS = 'html-fill-item'
FILL_CONTAINER_CLASS = 'html-fill-container'
FILL_ITEM_ATTRS: TagAttrs = {'class': FILL_ITEM_CLASS}
FILLABLE_CONTAINTER_ATTRS: TagAttrs = {'class': FILL_CONTAINER_CLASS}

@add_example()
def as_fillable_container(tag: TagT) -> TagT:
    res = copy(tag)
    res.add_class(FILL_CONTAINER_CLASS)
    res.append(fill_dependency())
    return res

@add_example()
def as_fill_item(tag: TagT) -> TagT:
    res = copy(tag)
    res.add_class(FILL_ITEM_CLASS)
    res.append(fill_dependency())
    return res

@no_example()
def remove_all_fill(tag: TagT) -> TagT:
    res = copy(tag)
    res.remove_class(FILL_CONTAINER_CLASS)
    res.remove_class(FILL_ITEM_CLASS)
    return res

def is_fillable_container(tag: object) -> bool:
    return isinstance(tag, Tag) and tag.has_class(FILL_CONTAINER_CLASS)

def is_fill_item(tag: object) -> bool:
    return isinstance(tag, Tag) and tag.has_class(FILL_ITEM_CLASS)

def query_by_short_id(context, model, short_id, project_safe=True):
    q = model_query(context, model)
    q = q.filter(model.id.like('%s%%' % short_id))
    if project_safe:
        q = q.filter_by(project=context.project)
    if q.count() == 1:
        return q.first()
    elif q.count() == 0:
        return None
    else:
        raise exception.MultipleChoices(arg=short_id)

